/**
 * Reliability score — v1, the 100-point model from the HirERP pitch (slide 28).
 * Mirror of back-end/src/reliability/reliability.service.ts — keep the two in sync.
 *
 *   Ирц, цаг баримтлалт   30 · Ажлын гүйцэтгэл 25 · Ажил олгогчийн үнэлгээ 20
 *   Баталгаажсан туршлага 15 · Найдвартай байдал 10
 *
 * No history ⇒ null ("шинэ / мэдээлэл дутуу"), parts without data are skipped
 * and the rest scaled to 100; no gender/age/health data is used (slide 30).
 */
import type { ID, ISODateTime } from '../types';
import { db } from './db';
import { addDays, monthsBetween, todayISO } from '../../lib/format';

export const ALGORITHM_VERSION = 'v1 · 100 онооны жишиг загвар';

export const WEIGHTS = { attendance: 30, performance: 25, rating: 20, experience: 15, reliability: 10 } as const;
const EXPERIENCE_FULL_MONTHS = 24;

export interface ReliabilityInputs {
  attendance: { onTime: number; late: number; absent: number; started: number; completed: number; recentNoShows: number };
  history: { months: number; avgAttendancePercent: number | null; lateCount: number; completedContracts: number; earlyTerminations: number; ended: number };
  tenure: { companyId: ID; months: number }[];
  ratings: number[];
  leave: { total: number; approved: number };
  contracts: { completed: number; total: number; declined: number };
  skills: number;
}

export type BreakdownKey = keyof typeof WEIGHTS;
export interface ScorePart {
  key: BreakdownKey;
  label: string;
  max: number;
  points: number | null;
  detail: string;
}
export interface ScoreResult {
  score: number | null;
  status: 'ok' | 'insufficient';
  breakdown: ScorePart[];
}

const LABELS: Record<BreakdownKey, string> = {
  attendance: 'Ирц, цаг баримтлалт',
  performance: 'Ажлын гүйцэтгэл',
  rating: 'Ажил олгогчийн үнэлгээ',
  experience: 'Баталгаажсан туршлага',
  reliability: 'Найдвартай байдал',
};

const round1 = (n: number) => Math.round(n * 10) / 10;
const pct = (n: number) => `${Math.round(n * 100)}%`;

/** Collects every input the scoring algorithm consumes. */
export function getReliabilityInputs(userId: ID): ReliabilityInputs {
  const since = addDays(todayISO(), -90);
  const records = db.attendance.filter((a) => a.userId === userId);
  const snapshots = db.historySnapshots.filter((h) => h.userId === userId && h.verified);
  const memberships = db.memberships.filter((m) => m.userId === userId && m.roleId !== 'role_owner');
  const count = (s: string) => records.filter((r) => r.status === s).length;
  const started = records.filter((r) => r.clockIn);
  const withAttendance = snapshots.filter((h) => h.attendancePercent != null);
  const contracts = db.contracts.filter((c) => c.userId === userId);
  const userLeave = db.leave.filter((l) => l.userId === userId);
  return {
    attendance: {
      onTime: count('on_time'),
      late: count('late'),
      absent: count('absent'),
      started: started.length,
      completed: started.filter((r) => r.clockOut).length,
      recentNoShows: records.filter((r) => r.status === 'absent' && r.date >= since).length,
    },
    history: {
      months: snapshots.reduce((s, h) => s + monthsBetween(h.startDate, h.endDate), 0),
      avgAttendancePercent: withAttendance.length ? withAttendance.reduce((s, h) => s + (h.attendancePercent ?? 0), 0) / withAttendance.length : null,
      lateCount: snapshots.reduce((s, h) => s + (h.lateCount ?? 0), 0),
      completedContracts: snapshots.filter((h) => h.outcome?.includes('хугацаандаа дууссан')).length,
      earlyTerminations: snapshots.filter((h) => h.outcome?.includes('цуцлагдсан')).length,
      ended: snapshots.length,
    },
    tenure: [
      ...memberships.map((m) => ({ companyId: m.companyId, months: monthsBetween(m.startDate, m.endDate) })),
      ...snapshots.map((s) => ({ companyId: s.companyId!, months: monthsBetween(s.startDate, s.endDate) })),
    ],
    ratings: [...db.ratings.filter((r) => r.userId === userId).map((r) => r.stars), ...snapshots.flatMap((s) => (s.avgRating ? [s.avgRating] : []))],
    leave: { total: userLeave.length, approved: userLeave.filter((l) => l.status === 'approved').length },
    contracts: {
      completed: snapshots.filter((h) => h.outcome?.includes('хугацаандаа дууссан')).length,
      total: snapshots.length + contracts.filter((c) => c.status === 'signed').length,
      declined: contracts.filter((c) => c.status === 'declined').length,
    },
    skills: db.users.find((u) => u.id === userId)?.skills.length ?? 0,
  };
}

/** Pure scoring function — the only place the algorithm lives. */
export function scoreFromInputs(i: ReliabilityInputs): ScoreResult {
  const totalMonths = i.tenure.reduce((s, t) => s + t.months, 0);
  const shifts = i.attendance.onTime + i.attendance.late + i.attendance.absent;
  const hasData = shifts > 0 || i.history.months > 0 || i.ratings.length > 0;

  let attendance: number | null = null;
  let attendanceDetail = 'Ирцийн бүртгэл алга';
  if (shifts > 0) {
    const showed = (i.attendance.onTime + i.attendance.late) / shifts;
    const punctual = i.attendance.onTime + i.attendance.late ? i.attendance.onTime / (i.attendance.onTime + i.attendance.late) : 0;
    attendance = WEIGHTS.attendance * (0.6 * showed + 0.4 * punctual);
    attendanceDetail = `Ирсэн ${pct(showed)} · цагтаа ${pct(punctual)} · ${shifts} ээлж`;
  } else if (i.history.avgAttendancePercent != null) {
    const showed = i.history.avgAttendancePercent / 100;
    const punctual = Math.max(0, 1 - i.history.lateCount / Math.max(1, i.history.months * 12));
    attendance = WEIGHTS.attendance * (0.6 * showed + 0.4 * punctual);
    attendanceDetail = `Өмнөх ажлуудын ирц ${pct(showed)}`;
  }

  const parts: number[] = [];
  const perfDetail: string[] = [];
  if (i.attendance.started > 0) {
    const r = i.attendance.completed / i.attendance.started;
    parts.push(r);
    perfDetail.push(`ээлж дуусгалт ${pct(r)}`);
  }
  if (i.history.ended > 0) {
    parts.push(i.history.completedContracts / i.history.ended);
    perfDetail.push(`гэрээ ${i.history.completedContracts}/${i.history.ended} хугацаандаа`);
  }
  const performance = parts.length ? WEIGHTS.performance * (parts.reduce((s, x) => s + x, 0) / parts.length) : null;

  const avg = i.ratings.length ? i.ratings.reduce((s, r) => s + r, 0) / i.ratings.length : null;
  const rating = avg != null ? WEIGHTS.rating * (avg / 5) : null;

  const experience = totalMonths > 0 ? WEIGHTS.experience * Math.min(1, totalMonths / EXPERIENCE_FULL_MONTHS) : null;

  const penalty = 2 * i.attendance.recentNoShows + 3 * i.history.earlyTerminations + i.contracts.declined;
  const reliability = hasData ? Math.max(0, WEIGHTS.reliability - penalty) : null;
  const relDetail =
    penalty === 0
      ? 'Урьдчилан мэдэгдэлгүй тасалсан бүртгэл алга'
      : [
          i.attendance.recentNoShows && `${i.attendance.recentNoShows} удаа ирээгүй (90 хоног)`,
          i.history.earlyTerminations && `${i.history.earlyTerminations} гэрээ эрт цуцалсан`,
          i.contracts.declined && `${i.contracts.declined} санал татгалзсан`,
        ]
          .filter(Boolean)
          .join(' · ');

  const breakdown: ScorePart[] = [
    { key: 'attendance', label: LABELS.attendance, max: WEIGHTS.attendance, points: attendance == null ? null : round1(attendance), detail: attendanceDetail },
    { key: 'performance', label: LABELS.performance, max: WEIGHTS.performance, points: performance == null ? null : round1(performance), detail: perfDetail.join(' · ') || 'Дуусгасан ажлын бүртгэл алга' },
    { key: 'rating', label: LABELS.rating, max: WEIGHTS.rating, points: rating == null ? null : round1(rating), detail: avg != null ? `Дундаж ${round1(avg)}/5 · ${i.ratings.length} үнэлгээ` : 'Үнэлгээ алга' },
    { key: 'experience', label: LABELS.experience, max: WEIGHTS.experience, points: experience == null ? null : round1(experience), detail: totalMonths ? `${totalMonths} сар баталгаажсан` : 'Баталгаажсан туршлага алга' },
    { key: 'reliability', label: LABELS.reliability, max: WEIGHTS.reliability, points: reliability == null ? null : round1(reliability), detail: relDetail },
  ];

  const scored = breakdown.filter((b) => b.points != null);
  if (!hasData || scored.length < 2) return { score: null, status: 'insufficient', breakdown };
  const earned = scored.reduce((s, b) => s + (b.points ?? 0), 0);
  const possible = scored.reduce((s, b) => s + b.max, 0);
  return { score: Math.round((earned / possible) * 100), status: 'ok', breakdown };
}

export function calculateReliabilityScore(userId: ID): { score: number | null; updatedAt: ISODateTime; result: ScoreResult } {
  const result = scoreFromInputs(getReliabilityInputs(userId));
  return { score: result.score, updatedAt: new Date().toISOString(), result };
}
